1	type Customer = { yearsWithMHPCO: number };
2	type Item = { type: string; material?: string; enchantment?: number; cursed?: boolean };
3	type Step = { op: "quote"; items: Item[] };
4	type Scenario = { customer: Customer; steps: Step[] };
5	
6	type QuoteResult = { premium: number };
7	type ScenarioResult = { results: QuoteResult[] };
8	
9	const PROCESSING_FEE = 5;
10	const FIRST_INSURANCE_PCT = 0.10;
11	const LOYALTY_PCT = 0.20;
12	const LOYALTY_YEARS = 2;
13	const FOLLOW_UP_PCT = 0.15;
14	const CURSE_PCT = 0.50;
15	const HIGH_ENCH_PCT = 0.30;
16	const HIGH_ENCH_THRESHOLD = 5;
17	const FLOAT_TOLERANCE = 1e-9;
18	const BLOCK_SIZE = 3;
19	const BLOCK_PREMIUM = 60;
20	
21	const BASE_PREMIUM: Record<string, number> = {
22	  sword: 100,
23	  amulet: 60,
24	  staff: 80,
25	  potion: 40,
26	  rune: 25,
27	  moonstone: 25,
28	};
29	
30	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
31	
32	const isComponentType = (type: string): boolean => COMPONENT_TYPES.has(type);
33	
34	const roundUp = (n: number): number => Math.ceil(n - FLOAT_TOLERANCE);
35	
36	const countByType = (items: Item[]): Map<string, number> => {
37	  const counts = new Map<string, number>();
38	  for (const item of items) {
39	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
40	  }
41	  return counts;
42	};
43	
44	const groupBasePremium = (type: string, count: number): number =>
45	  isComponentType(type) && count === BLOCK_SIZE
46	    ? BLOCK_PREMIUM
47	    : count * BASE_PREMIUM[type];
48	
49	const sumBasePremiums = (items: Item[]): number => {
50	  let total = 0;
51	  for (const [type, count] of countByType(items)) {
52	    total += groupBasePremium(type, count);
53	  }
54	  return total;
55	};
56	
57	const isHighlyEnchanted = (item: Item): boolean =>
58	  (item.enchantment ?? 0) >= HIGH_ENCH_THRESHOLD;
59	
60	const itemSurchargePct = (item: Item): number =>
61	  (item.cursed ? CURSE_PCT : 0) +
62	  (isHighlyEnchanted(item) ? HIGH_ENCH_PCT : 0);
63	
64	const itemSurcharge = (item: Item): number =>
65	  BASE_PREMIUM[item.type] * itemSurchargePct(item);
66	
67	const itemSurcharges = (items: Item[]): number =>
68	  items.reduce((total, item) => total + itemSurcharge(item), 0);
69	
70	const loyaltyDiscountPct = (customer: Customer): number =>
71	  customer.yearsWithMHPCO >= LOYALTY_YEARS ? LOYALTY_PCT : 0;
72	
73	const followUpDiscountPct = (priorQuoteCount: number): number =>
74	  priorQuoteCount > 0 ? FOLLOW_UP_PCT : 0;
75	
76	const policyBaseMultiplier = (customer: Customer, priorQuoteCount: number): number =>
77	  1 + FIRST_INSURANCE_PCT - loyaltyDiscountPct(customer) - followUpDiscountPct(priorQuoteCount);
78	
79	const computeQuotePremium = (items: Item[], customer: Customer, priorQuoteCount: number): number => {
80	  const policyBase = sumBasePremiums(items);
81	  return roundUp(
82	    policyBase * policyBaseMultiplier(customer, priorQuoteCount) + itemSurcharges(items) + PROCESSING_FEE,
83	  );
84	};
85	
86	export const runScenario = (scenario: Scenario): ScenarioResult => {
87	  const results: QuoteResult[] = [];
88	  let quoteCount = 0;
89	  for (const step of scenario.steps) {
90	    results.push({ premium: computeQuotePremium(step.items, scenario.customer, quoteCount) });
91	    quoteCount++;
92	  }
93	  return { results };
94	};
